      { name: "Eccentric training, manual therapy, stretching and pulsed Nd-YAG laser", description: "A professional motorcycle rider recovered fully and was durable at 5 months after rest, a splint, NSAIDs and physiotherapy including pulsed Nd-YAG laser, stretching and release, massage and eccentric training. This is a single case; the authors propose laser as an additional option, but its contribution cannot be separated [r11].", evidence: "very-limited", recommendation: "consider", refs: ["r11"] },
      { name: "Continuing the aggravating pattern (high-volume repetitive wrist extension or wide-grip lifting) through acute swelling", description: "The condition is an overuse problem, and repetitive wrist extension under load is the aggravating factor [r9,r7]. Offload during the acute phase while keeping the rest of the body training (clinical reasoning).", evidence: "expert-opinion", recommendation: "not-recommended", refs: [] }
